import {allowedPages,getPersonal,sanitizePersonal,cleanIds} from './personal-preferences.js?v=2.79';
import {widgetCatalog,cleanWidgetSizes} from '../personal-widgets.js?v=2.79';
import {preferences,normalizePreference} from '../layout-controller.js?v=2.79';
import {currentAppearanceMode} from '../appearance.js?v=2.79';
const keys={personal:'csanadi.personal-settings.v1',favorites:'csanadi.page-favorites.v1',history:'csanadi.page-history.v1',historyEnabled:'csanadi.page-history.enabled.v1',widgets:'csanadi.personal-widgets.v1',sizes:'csanadi.personal-widget-sizes.v1',grouped:'csanadi.widget-grouped.v1',documents:'csanadi.document-favorites.v1',layout:'csanadi-adaptive-preferences-v1'};
const json=(store,k,fallback)=>{const s=store.getItem(k);return s===null?fallback:JSON.parse(s);};
export function bundleSnapshot(config,store=localStorage,includeHistory=false){const allow=allowedPages(config),widgets=new Set(widgetCatalog(config).flatMap(g=>g.items.map(x=>x.id))),docs=new Set(config.documentCenter.items.map(x=>x.id));const list=(key,allowed,max,fallback=[])=>{const x=json(store,key,fallback);return Array.isArray(x)?[...new Set(x.filter(v=>allowed.has(v)))].slice(0,max):[];};return {schema:'csanadi-personal-1',theme:currentAppearanceMode(config),layout:preferences(),personal:getPersonal(config),favorites:list(keys.favorites,allow,66),historyEnabled:store.getItem(keys.historyEnabled)!=='false',history:includeHistory?list(keys.history,allow,20):null,widgets:list(keys.widgets,widgets,config.home.widgets.maxItems,config.home.widgets.defaults),sizes:cleanWidgetSizes(json(store,keys.sizes,{}),widgets),grouped:store.getItem(keys.grouped)==='true',documents:list(keys.documents,docs,docs.size)};}
export function validateBundle(config,raw){if(!raw||raw.schema!=='csanadi-personal-1'||!config.appearance.cycle.includes(raw.theme)||raw.layout?.version!==1||raw.personal?.version!==1||typeof raw.historyEnabled!=='boolean'||typeof raw.grouped!=='boolean'||typeof raw.layout.remember!=='boolean')throw Error('Érvénytelen személyes mentés.');const layout=normalizePreference(raw.layout);if(Object.entries(layout).some(([k,v])=>raw.layout[k]!==v))throw Error('Érvénytelen megjelenítési beállítás.');const allow=allowedPages(config),widgets=new Set(widgetCatalog(config).flatMap(g=>g.items.map(x=>x.id))),docs=new Set(config.documentCenter.items.map(x=>x.id));const sizes=cleanWidgetSizes(raw.sizes,widgets);if(!raw.sizes||typeof raw.sizes!=='object'||Array.isArray(raw.sizes)||Object.keys(raw.sizes).length!==Object.keys(sizes).length)throw Error('Érvénytelen widgetméret.');return {schema:raw.schema,theme:raw.theme,layout,personal:sanitizePersonal(raw.personal,allow),favorites:cleanIds(raw.favorites,allow,66),historyEnabled:raw.historyEnabled,history:raw.history===null?null:cleanIds(raw.history,allow,20),widgets:cleanIds(raw.widgets,widgets,config.home.widgets.maxItems),sizes,grouped:raw.grouped,documents:cleanIds(raw.documents,docs,docs.size)};}
export function writeBundle(config,raw,store=localStorage,session=sessionStorage){const p=validateBundle(config,raw),changes=new Map([[config.appearance.storageKey,p.theme],[keys.personal,JSON.stringify(p.personal)],[keys.favorites,JSON.stringify(p.favorites)],[keys.historyEnabled,String(p.historyEnabled)],[keys.widgets,JSON.stringify(p.widgets)],[keys.sizes,JSON.stringify(p.sizes)],[keys.grouped,String(p.grouped)],[keys.documents,JSON.stringify(p.documents)],[keys.layout,p.layout.remember?JSON.stringify(p.layout):null]]);if(!p.historyEnabled||p.history!==null)changes.set(keys.history,JSON.stringify(p.historyEnabled?p.history||[]:[]));const old=new Map([...changes.keys()].map(k=>[k,store.getItem(k)]));const handoff='csanadi-layout-import-once';const oldSession=session.getItem(handoff);try{for(const [k,v] of changes)v===null?store.removeItem(k):store.setItem(k,v);if(p.layout.remember)session.removeItem(handoff);else session.setItem(handoff,JSON.stringify(p.layout));}catch(e){try{for(const [k,v] of old)v===null?store.removeItem(k):store.setItem(k,v);oldSession===null?session.removeItem(handoff):session.setItem(handoff,oldSession);}catch{}throw Error('Nem sikerült a beállításokat menteni. Ellenőrizd a böngésző tárhelyét.');}return p;}
